63	    pub fn write(&self, buffer: &mut Buffer) {
64	        use std::io::Write;
65	        match &self.location {
66	            Some(location) => self.write_span(location, buffer),
67	            None => self.write_title(buffer),
68	        };
69	
70	        if !self.text.is_empty() {
71	            writeln!(buffer, "{}", self.text).expect("write text");
72	        }
73	
74	        if let Some(hint) = &self.hint {
75	            writeln!(buffer, "Hint: {hint}").expect("write hint");
76	        }
77	    }
