79	    fn write_span(&self, location: &Location, buffer: &mut Buffer) {
80	        let mut file_map = HashMap::new();
81	        let mut files = SimpleFiles::new();
82	
83	        let main_location_path = location.path.as_str();
84	        let main_location_src = location.src.as_str();
85	        let main_file_id = files.add(main_location_path, main_location_src);
86	        let _ = file_map.insert(main_location_path, main_file_id);
87	
88	        let mut labels = vec![
89	            location
90	                .label
91	                .to_codespan_label(main_file_id, LabelStyle::Primary),
92	        ];
93	
94	        location
95	            .extra_labels
96	            .iter()
97	            .map(|label| {
98	                let (location_src, location_path) = match &label.src_info {
99	                    Some(info) => (info.0.as_str(), info.1.as_str()),
100	                    _ => (main_location_src, main_location_path),
101	                };
102	                match file_map.get(location_path) {
103	                    None => {
104	                        let file_id = files.add(location_path, location_src);
105	                        let _ = file_map.insert(location_path, file_id);
106	                        label
107	                            .label
108	                            .to_codespan_label(file_id, LabelStyle::Secondary)
109	                    }
110	                    Some(i) => label.label.to_codespan_label(*i, LabelStyle::Secondary),
111	                }
112	            })
113	            .for_each(|label| labels.push(label));
114	
115	        let severity = match self.level {
116	            Level::Error => Severity::Error,
117	            Level::Warning => Severity::Warning,
118	        };
119	
120	        let diagnostic = codespan_reporting::diagnostic::Diagnostic::new(severity)
121	            .with_message(&self.title)
122	            .with_labels(labels);
123	        let config = codespan_reporting::term::Config::default();
124	        codespan_reporting::term::emit(buffer, &config, &files, &diagnostic)
125	            .expect("write_diagnostic");
126	    }
127	
128	    fn write_title(&self, buffer: &mut Buffer) {
129	        use std::io::Write;
130	        use termcolor::{Color, ColorSpec, WriteColor};
131	        let (kind, colour) = match self.level {
132	            Level::Error => ("error", Color::Red),
133	            Level::Warning => ("warning", Color::Yellow),
134	        };
135	        buffer
136	            .set_color(ColorSpec::new().set_bold(true).set_fg(Some(colour)))
137	            .expect("write_title_color1");
138	        write!(buffer, "{kind}").expect("write_title_kind");
139	        buffer
140	            .set_color(ColorSpec::new().set_bold(true))
141	            .expect("write_title_color2");
142	        write!(buffer, ": {}\n\n", self.title).expect("write_title_title");
143	        buffer
144	            .set_color(&ColorSpec::new())
145	            .expect("write_title_reset");
146	    }
147	}
